/* ============================================
   CreativeHub — Global Styles
   ============================================ */

:root {
  --primary: #F02D00;
  --primary-hover: #d12600;
  --dark: #171717;
  --light: #FFFFFF;
  --gray-50: #FAFAFA;
  --gray-100: #F5F5F5;
  --gray-200: #E5E5E5;
  --gray-300: #D4D4D4;
  --gray-400: #A3A3A3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --gray-900: #171717;
  --success: #22C55E;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.12);
  --transition: 0.25s ease;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--dark);
  background: var(--light);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }

img { max-width: 100%; display: block; }

button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ============================================
   Header
   ============================================ */

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--light);
  border-bottom: 1px solid var(--gray-200);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.5px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.logo-mark {
  width: 28px; height: 28px;
  background: var(--primary);
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 14px;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 28px;
}

.header-nav a {
  font-size: 14px;
  font-weight: 500;
  color: var(--gray-700);
  transition: color var(--transition);
}
.header-nav a:hover { color: var(--dark); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.search-btn {
  width: 36px; height: 36px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  color: var(--gray-600);
  transition: background var(--transition);
}
.search-btn:hover { background: var(--gray-100); }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 18px;
  font-size: 14px;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all var(--transition);
}

.btn-sm { padding: 6px 14px; font-size: 13px; }

.btn-primary {
  background: var(--primary);
  color: #fff;
}
.btn-primary:hover { background: var(--primary-hover); }

.btn-outline {
  background: transparent;
  color: var(--dark);
  border: 1.5px solid var(--gray-300);
}
.btn-outline:hover { border-color: var(--dark); }

.btn-dark {
  background: var(--dark);
  color: #fff;
}
.btn-dark:hover { background: var(--gray-800); }

.mobile-menu-btn {
  display: none;
  width: 36px; height: 36px;
  align-items: center; justify-content: center;
}

/* ============================================
   Promo Banner
   ============================================ */

.promo-banner {
  background: var(--dark);
  color: #fff;
  font-size: 13px;
  padding: 10px 0;
  position: relative;
}

.promo-banner-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.promo-banner .countdown {
  font-weight: 700;
  color: #FFD700;
  font-variant-numeric: tabular-nums;
}

.promo-banner .close-banner {
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
  width: 24px; height: 24px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 4px;
}
.promo-banner .close-banner:hover { color: #fff; background: rgba(255,255,255,0.1); }

/* ============================================
   Footer
   ============================================ */

.site-footer {
  background: var(--gray-50);
  border-top: 1px solid var(--gray-200);
  padding: 56px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-bottom: 14px;
  color: var(--gray-700);
}

.footer-col ul { list-style: none; }

.footer-col li { margin-bottom: 8px; }

.footer-col a {
  font-size: 13px;
  color: var(--gray-500);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--dark); }

.footer-bottom {
  margin-top: 40px;
  padding-top: 24px;
  border-top: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom .logo { font-size: 18px; }

.footer-legal {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
}

.footer-legal a {
  font-size: 12px;
  color: var(--gray-400);
}

.footer-apps {
  display: flex;
  gap: 10px;
}

.app-badge {
  height: 32px;
  background: var(--dark);
  color: #fff;
  border-radius: var(--radius-sm);
  padding: 0 12px;
  font-size: 11px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.footer-accordion-toggle {
  display: none;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  font-size: 14px;
  font-weight: 700;
  border-bottom: 1px solid var(--gray-200);
}

/* ============================================
   Carousels
   ============================================ */

.carousel-wrap { position: relative; }

.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 4px;
}
.carousel-track::-webkit-scrollbar { display: none; }

.carousel-slide {
  scroll-snap-align: start;
  flex-shrink: 0;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px; height: 40px;
  border-radius: 50%;
  background: var(--light);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow-md);
  display: flex; align-items: center; justify-content: center;
  color: var(--dark);
  z-index: 5;
  transition: all var(--transition);
}
.carousel-arrow:hover { background: var(--gray-100); }
.carousel-arrow.prev { left: -20px; }
.carousel-arrow.next { right: -20px; }
.carousel-arrow:disabled { opacity: 0; pointer-events: none; }

/* ============================================
   Course Cards
   ============================================ */

.course-card {
  background: var(--light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: box-shadow var(--transition), transform var(--transition);
}
.course-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.course-thumb {
  position: relative;
  aspect-ratio: 16 / 10;
  background: var(--gray-100);
  overflow: hidden;
}

.course-thumb img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform var(--transition);
}
.course-card:hover .course-thumb img { transform: scale(1.04); }

.course-badge {
  position: absolute;
  top: 10px; left: 10px;
  background: var(--primary);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
}

.course-info { padding: 14px; }

.course-title {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.35;
  margin-bottom: 6px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-meta {
  font-size: 12px;
  color: var(--gray-500);
  margin-bottom: 10px;
}

.course-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.course-rating {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 600;
  color: var(--gray-700);
}

.course-price {
  font-size: 15px;
  font-weight: 700;
}

.course-price .was {
  font-size: 12px;
  color: var(--gray-400);
  text-decoration: line-through;
  margin-left: 4px;
  font-weight: 500;
}

/* ============================================
   Sections
   ============================================ */

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 24px;
}

.section-title {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.3px;
}

.section-subtitle {
  font-size: 14px;
  color: var(--gray-500);
  margin-top: 4px;
}

/* ============================================
   Responsive
   ============================================ */

@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .carousel-arrow.prev { left: 8px; }
  .carousel-arrow.next { right: 8px; }
}

@media (max-width: 768px) {
  .header-nav { display: none; }
  .mobile-menu-btn { display: flex; }
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-col { display: none; }
  .footer-col.open { display: block; }
  .footer-accordion-toggle { display: flex; }
  .section-title { font-size: 20px; }
  .footer-bottom {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .btn { padding: 8px 14px; font-size: 13px; }
}

/* ============================================
   CreativeHub — Shared Scripts
   ============================================ */

// Promo banner dismiss
(function () {
  const banner = document.querySelector('.promo-banner');
  if (!banner) return;
  const closeBtn = banner.querySelector('.close-banner');
  if (!closeBtn) return;
  closeBtn.addEventListener('click', () => {
    banner.style.display = 'none';
    localStorage.setItem('ch_banner_closed', '1');
  });
  if (localStorage.getItem('ch_banner_closed') === '1') {
    banner.style.display = 'none';
  }
})();

// Countdown timer
(function () {
  const el = document.querySelector('.countdown');
  if (!el) return;
  let h = 5, m = 42, s = 18;
  const pad = n => String(n).padStart(2, '0');
  setInterval(() => {
    if (s === 0) { if (m === 0) { if (h === 0) { h = 23; m = 59; s = 59; } else { h--; m = 59; s = 59; } } else { m--; s = 59; } } else { s--; }
    el.textContent = `${pad(h)}:${pad(m)}:${pad(s)}`;
  }, 1000);
})();

// Mobile footer accordion
(function () {
  const toggles = document.querySelectorAll('.footer-accordion-toggle');
  toggles.forEach(t => {
    t.addEventListener('click', () => {
      const col = t.nextElementSibling;
      const icon = t.querySelector('.acc-icon');
      const isOpen = col.classList.toggle('open');
      if (icon) icon.textContent = isOpen ? '−' : '+';
    });
  });
})();

// Generic carousel helper
function initCarousel(trackSelector, prevSelector, nextSelector) {
  const track = document.querySelector(trackSelector);
  if (!track) return;
  const prev = document.querySelector(prevSelector);
  const next = document.querySelector(nextSelector);
  const scrollAmount = 320;

  function updateArrows() {
    if (prev) prev.disabled = track.scrollLeft <= 1;
    if (next) next.disabled = track.scrollLeft + track.clientWidth >= track.scrollWidth - 1;
  }

  if (prev) prev.addEventListener('click', () => { track.scrollBy({ left: -scrollAmount, behavior: 'smooth' }); });
  if (next) next.addEventListener('click', () => { track.scrollBy({ left: scrollAmount, behavior: 'smooth' }); });
  track.addEventListener('scroll', updateArrows);
  updateArrows();
}

// Intersection reveal
(function () {
  const obs = new IntersectionObserver((entries) => {
    entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('revealed'); obs.unobserve(e.target); } });
  }, { threshold: 0.1 });
  document.querySelectorAll('.reveal').forEach(el => obs.observe(el));
})();
